'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',folder:'<path d="M3 7V5h7l3 3h8v12H3z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8" cy="8" r="2"/><path d="m3 17 5-5 4 4 4-6 5 7"/>',video:'<rect x="3" y="4" width="18" height="16" rx="3"/><path d="m10 8 6 4-6 4z"/>',database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>',record:'<path d="M5 3h11l3 3v15H5zM9 9h6m-6 4h6m-6 4h4"/>',grid:'<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h1M3 12h1M3 19h1"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',plus:'<path d="M12 4v16M4 12h16"/>',play:'<path d="m7 3 14 9-14 9z"/>',frame:'<path d="M3 8V3h5m8 0h5v5m0 8v5h-5M8 21H3v-5"/><circle cx="12" cy="12" r="4"/>'};
let svg=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[k]||icons.record}</svg>`;
const typeNames={image:'图片',video:'视频',database:'数据库',record:'条目'},statusNames={pending:'待看',watched:'看过',watching:'在看'};
const state={library:{items:[],sources:[],categories:[...YingjiCategories.DEFAULTS]},tab:'library',type:'all',query:'',category:'all',year:'all',status:'all',sort:'recent',view:localStorage.getItem('yingji-view')||'grid',limit:40,loading:false};let current=null,dbState=null,focusBefore=null,scanCount=0;const thumbnailCache=new Map();const thumbnailQueue=[];let thumbRunning=0,jobRunning=false;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function bytes(n){if(!n)return'—';const units=['B','KB','MB','GB'];let i=0;while(n>=1024&&i<3){n/=1024;i++}return n.toFixed(i?1:0)+' '+units[i]}
function time(n){if(!Number.isFinite(n))return'00:00';const h=Math.floor(n/3600),m=Math.floor(n%3600/60),s=Math.floor(n%60);return(h?h+':':'')+String(m).padStart(2,'0')+':'+String(s).padStart(2,'0')}
const options=(values,selected)=>values.map(([v,t])=>`<option value="${esc(v)}"${v===selected?' selected':''}>${esc(t)}</option>`).join('');
function select(id,values,selected){return`<div class="select-wrap"><select id="${id}" aria-label="${({filterCategory:'类目',filterYear:'出品年份',filterSort:'排序',catalogProvider:'作品数据源',catalogKind:'作品类型',catalogYear:'作品出品年份',catalogSort:'作品排序'})[id]||'筛选条件'}">${options(values,selected)}</select></div>`}
async function invoke(name,args){if(!window.yingji)throw Error('请在 Windows 桌面程序中使用本地文件功能');return await window.yingji[name](args)}
function acceptLibrary(lib){if(!lib)return;state.library=lib;state.loading=false;thumbnailCache.clear();state.limit=40;state.category='all';state.year='all';render();if(lib.errors?.length)toast(`已读取；${lib.errors.length} 个文件未能展开，可在详情查看原因`)}
async function importFolder(){try{state.loading=true;const r=await invoke('chooseFolder');acceptLibrary(r)}catch(e){toast(e.message)}finally{state.loading=false}}
async function importFiles(){try{state.loading=true;const r=await invoke('chooseFiles');acceptLibrary(r)}catch(e){toast(e.message)}finally{state.loading=false}}
async function rescan(){if(state.loading)return;try{state.loading=true;toast('正在重新读取文件来源…');acceptLibrary(await invoke('rescan'));toast('读取完成，资料已更新')}catch(e){toast(e.message)}finally{state.loading=false}}
function counts(){const c={image:0,video:0,database:0,record:0};const visible=window.YingjiMarks?.visibleIds(state.library.items);state.library.items.filter(i=>!visible||visible.has(i.id)).forEach(i=>c[i.type]++);return c}
function heading(kicker,title,sub){return`<p class="eyebrow">${kicker}</p><div class="heading-row"><h1>${title}</h1></div>${sub?`<p class="intro">${sub}</p>`:''}`}
function render(){document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===state.tab));if(state.tab==='library')renderLibrary();else if(state.tab==='sources')renderSources();else if(state.tab==='database')renderDatabases();else renderSettings()}

let preferences={theme:'system',density:'comfortable',zoom:1};try{preferences={...preferences,...JSON.parse(localStorage.getItem('yingji-preferences')||'{}')}}catch{}
const themeNames={system:'跟随系统',midnight:'夜间',day:'白天',forest:'森林',ocean:'海蓝',sunset:'暮色'};
const themeSwatches={system:['#ece6f1','#242130','#b9a5ff'],midnight:['#11121b','#30243c','#b9a5ff'],day:['#f5f3f9','#eae4f3','#7151ac'],forest:['#111c19','#293a2e','#b7d79d'],ocean:['#101c26','#243b49','#91cde5'],sunset:['#20151f','#402b3d','#e7a9bc']};
function applyPreferences(){document.body.dataset.theme=preferences.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'midnight':'day'):preferences.theme;document.body.dataset.density=preferences.density;localStorage.setItem('yingji-preferences',JSON.stringify(preferences))}
applyPreferences();matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(preferences.theme==='system')applyPreferences()});
async function updatePreferences(p){preferences={...preferences,...p};applyPreferences();try{preferences=await invoke('setPreferences',preferences)}catch(e){toast(e.message)}if(state.tab==='settings')renderSettings()}
function appearancePanel(){return '<div class="panel"><h3>外观与高分屏</h3><div class="theme-grid">'+Object.entries(themeNames).map(([k,v])=>'<button class="theme-option '+(preferences.theme===k?'active':'')+'" data-theme-choice="'+k+'" aria-label="'+v+'主题"><div class="theme-colors">'+themeSwatches[k].map(c=>'<i style="background:'+c+'"></i>').join('')+'</div><span>'+v+'</span></button>').join('')+'</div><div class="appearance-row"><span>界面缩放</span><div class="zoom-controls"><button data-zoom="-1" aria-label="缩小界面">−</button><output>'+Math.round(preferences.zoom*100)+'%</output><button data-zoom="1" aria-label="放大界面">+</button></div></div><p class="hint">75%–200% · Ctrl + / Ctrl − 调整 · Ctrl 0 恢复<br>高分屏使用系统像素密度，缩放不改变素材原始分辨率。</p><div class="appearance-row"><span>布局样式</span></div><div class="density-options">'+[['compact','紧凑'],['comfortable','舒适'],['poster','大封面']].map(([k,v])=>'<button data-density-choice="'+k+'" class="'+(preferences.density===k?'active':'')+'">'+v+'</button>').join('')+'</div></div>'}
document.addEventListener('click',e=>{const t=e.target.closest('[data-theme-choice]');if(t)updatePreferences({theme:t.dataset.themeChoice});const d=e.target.closest('[data-density-choice]');if(d)updatePreferences({density:d.dataset.densityChoice});const z=e.target.closest('[data-zoom]');if(z)updatePreferences({zoom:Math.max(.75,Math.min(2,Math.round((preferences.zoom+Number(z.dataset.zoom)*.1)*100)/100))})});
document.addEventListener('keydown',e=>{if(!e.ctrlKey)return;if(['+','=','-','0'].includes(e.key)){e.preventDefault();updatePreferences({zoom:e.key==='0'?1:Math.max(.75,Math.min(2,Math.round((preferences.zoom+(e.key==='-'?-.1:.1))*100)/100))})}});

function renderLibrary(){const c=counts(),cats=[...new Set([...(state.library.categories||['电影','动漫','小说','漫画']),...state.library.items.map(i=>i.category).filter(Boolean)])],years=[...new Set(state.library.items.map(i=>i.date?.slice(0,4)).filter(y=>/^\d{4}$/.test(y)))].sort().reverse();$('#main').innerHTML=heading('MY MEDIA ARCHIVE','喜欢的故事，<em>有处安放。</em>','本地素材与作品资料，一处轻松浏览。')+`<div class="reader-hero"><div class="hero-kicker">MAKE ROOM FOR YOUR STORIES</div><h2>散落的素材，<br>自己的<em>小宇宙。</em></h2><p>选择一个文件夹，开始你的资料库。</p><button data-action="folder">${svg('plus')} 读取本地文件夹</button><div class="hero-art"><div class="art-back"></div><div class="art-front"></div><div class="art-label">YOUR OWN COLLECTION</div></div></div>${state.library.demo?'<div class="example-banner"><span>示例资料库 · 下方内容用于体验</span><button data-action="folder">读取我的文件</button></div>':''}<div class="stats-inline"><div><b>${c.image}</b><span>图片</span></div><div><b>${c.video}</b><span>视频</span></div><div><b>${c.record}</b><span>条目</span></div><div><b>${c.database}</b><span>数据库</span></div></div><div class="search">${svg('search')}<input id="searchInput" aria-label="搜索资料库" placeholder="搜索名称、作者、标签或文件名…" value="${esc(state.query)}"><span class="key">/</span></div><div class="type-tabs">${[['all','全部'],['record','作品条目'],['image','图片'],['video','视频'],['database','数据库']].map(([k,t])=>`<button class="chip ${state.type===k?'active':''}" data-type="${k}">${t}</button>`).join('')}</div><div class="reader-filters">${select('filterCategory',[['all','所有类目'],...cats.map(c=>[c,c])],state.category)}${select('filterYear',[['all','出品年份'],...years.map(y=>[y,y+' 年'])],state.year)}${select('filterSort',[['recent','最近读取'],['name','名称排序'],['date','出品时间'],['size','文件大小']],state.sort)}</div><div class="filters-toggle"><label for="filterStatus">观看状态</label><select id="filterStatus" aria-label="观看状态">${options([['all','全部状态'],...Object.entries(statusNames)],state.status)}</select><button class="ghost-link" data-action="edit-new">添加条目</button></div><div class="section-line"><h2 id="resultHeading">资料库 <small id="resultCount"></small></h2><div class="view-switch"><button aria-label="封面视图" data-view="grid" class="${state.view==='grid'?'active':''}">${svg('grid')}</button><button aria-label="列表视图" data-view="list" class="${state.view==='list'?'active':''}">${svg('list')}</button></div></div><div id="resultList"></div><p class="reader-status">${svg('lock')} 文件在本机读取 · 不上传素材<br>出品时间来自条目资料，未填写的不会使用文件日期代替</p>`;$('#searchInput').addEventListener('input',e=>{state.query=e.target.value;state.limit=40;renderResults()});for(const[id,key]of [['filterCategory','category'],['filterYear','year'],['filterSort','sort'],['filterStatus','status']])$('#'+id).addEventListener('change',e=>{state[key]=e.target.value;state.limit=40;renderResults()});renderResults()}
function filtered(){let items=state.library.items.filter(i=>(state.type==='all'||i.type===state.type)&&(state.category==='all'||i.category===state.category)&&(state.year==='all'||i.date?.startsWith(state.year))&&(state.status==='all'||i.status===state.status));const q=state.query.trim().toLowerCase();if(q)items=items.filter(i=>[i.title,i.author,i.tags,i.filename,i.category,i.relativePath].join(' ').toLowerCase().includes(q));return items.sort((a,b)=>state.sort==='name'?a.title.localeCompare(b.title,'zh-CN'):state.sort==='date'?(b.date||'').localeCompare(a.date||''):state.sort==='size'?(b.size||0)-(a.size||0):(b.modified||'').localeCompare(a.modified||''))}
function placeholder(i){return`<div class="cover-placeholder">${i.type==='record'?`<span class="record-cover-word">${esc(i.title.slice(0,5))}</span>`:svg(i.type)}</div>`}
function cover(i){return`<div data-thumbnail="${esc(i.coverId||i.id)}">${placeholder(i)}</div>`}
function card(i){const status=i.type==='record'?`<span class="record-status">${statusNames[i.status]||'未观看'}</span>`:'';return`<article class="media-card" data-open="${esc(i.id)}" tabindex="0" role="button" aria-label="打开 ${esc(i.title)}"><div class="media-cover">${cover(i)}<span class="file-type">${esc(i.type==='record'?i.category:typeNames[i.type])}</span>${status}<div class="cover-bottom"><span>${esc(i.type==='record'?(i.date||'出品时间未填写'):i.extension||'文件')}</span>${i.type==='video'?`<b class="play-dot">${svg('play')}</b>`:i.type!=='record'?`<span>${bytes(i.size)}</span>`:''}</div></div><h3>${esc(i.title)}</h3><p>${esc(i.type==='record'?(i.author||i.category||'未分类'):(i.folder||i.relativePath))}</p></article>`}
function listRow(i){return`<article class="work-row" data-open="${esc(i.id)}" tabindex="0" role="button" aria-label="打开 ${esc(i.title)}"><div class="list-thumb">${cover(i)}</div><div class="work-main"><h3 class="work-title">${esc(i.title)}</h3><p class="work-original">${esc(i.author||i.relativePath||'手动添加')}</p><div class="work-meta"><span class="type-badge">${esc(i.category||'未分类')}</span><span>${esc(i.date||'出品时间未填写')}</span>${i.score?`<span class="rating">${i.score}</span>`:''}</div></div><span class="open-file">›</span></article>`}
function renderResults(){const items=filtered();$('#resultCount').textContent=items.length+' 项';$('#resultHeading').firstChild.textContent=state.query?'搜索结果 ':'资料库 ';$('#resultList').innerHTML=items.length?`<div class="${state.view==='grid'?'file-grid':'file-list'}">${items.slice(0,state.limit).map(state.view==='grid'?card:listRow).join('')}</div>${items.length>state.limit?`<button class="load-more" data-action="more">显示更多 · 还有 ${items.length-state.limit} 项</button>`:''}`:`<div class="empty-reader">${svg('folder')}<h3>${state.library.items.length?'没有匹配的内容':'你的资料库，等你装满'}</h3><p>${state.library.items.length?'试试其他关键词或筛选条件。':'读取一个文件夹，或手动添加电影、动漫、小说和漫画。'}</p><button data-action="${state.library.items.length?'clear-filters':'folder'}">${state.library.items.length?'清除筛选':'读取本地文件夹'}</button></div>`;queueThumbnails()}
function queueThumbnails(){const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){observer.unobserve(e.target);const id=e.target.dataset.thumbnail;if(thumbnailCache.has(id)){setThumbnail(e.target,thumbnailCache.get(id));continue}const item=state.library.items.find(i=>i.id===id);if(!item||!['image','video'].includes(item.type))continue;thumbnailQueue.push({id,node:e.target});pumpThumbnails()}},{rootMargin:'150px'});document.querySelectorAll('[data-thumbnail]').forEach(n=>observer.observe(n))}
function setThumbnail(node,url){if(url&&node.isConnected){node.innerHTML=`<img src="${esc(url)}" alt="" loading="lazy">`;node.style.width='100%';node.style.height='100%'}}
async function pumpThumbnails(){if(thumbRunning>=2||!thumbnailQueue.length)return;const task=thumbnailQueue.shift();if(!task.node.isConnected){pumpThumbnails();return}thumbRunning++;try{const url=await invoke('thumbnail',task.id);thumbnailCache.set(task.id,url);setThumbnail(task.node,url)}catch{}finally{thumbRunning--;pumpThumbnails()}}
function renderSources(){const sources=state.library.sources||[];$('#main').innerHTML=heading('LOCAL SOURCES','文件的<em>来处。</em>','直接连接本地文件，素材不用搬家。')+`<div class="source-controls"><button class="button" data-action="folder">${svg('folder')}读取文件夹</button><button class="button secondary" data-action="files">${svg('plus')}选择文件</button></div>${state.library.demo?'<div class="example-banner">当前为示例资料库，读取你自己的文件后自动切换。</div>':''}${sources.map(s=>{const count=state.library.items.filter(i=>i.source===s||i.path===s).length;return`<div class="source-card"><div class="source-icon">${svg('folder')}</div><div class="source-info"><h3>${esc(s.split(/[\\/]/).pop())}</h3><p title="${esc(s)}">${esc(s)}</p><small>本地连接 · ${count} 项内容</small></div><span>${count}</span></div>`}).join('')||'<div class="empty-reader"><h3>还没有文件来源</h3><p>选择文件夹后，程序会记住位置，重开时可继续浏览。</p></div>'}<button class="button secondary wide" data-action="rescan">重新扫描所有来源</button><div class="drop-mini">${svg('folder')}也可以把图片、视频或数据库文件拖到窗口里<br>扫描跳过隐藏文件夹与符号链接</div><div class="panel"><h3>读取范围</h3><p>支持常见图片、视频，以及 JSON、JSONL、CSV、TSV、SQLite 数据库。SQLite 以只读方式打开；通用 JSON / CSV 记录会建立本地搜索索引。</p><div class="support-tags">${['JPG / PNG / WEBP','MP4 / MKV / MOV','JSON / CSV','SQLite / DB'].map(t=>`<span>${t}</span>`).join('')}</div></div><p class="reader-status">上次读取：${state.library.updatedAt?new Date(state.library.updatedAt).toLocaleString('zh-CN'):'尚未读取'}</p>`}
function renderDatabases(){const files=state.library.items.filter(i=>i.type==='database');$('#main').innerHTML=heading('DATA EXPLORER','打开你的<em>数据库。</em>','查看数据表、搜索记录，保留原始结构。')+`<div class="import-line"><button class="button" data-action="files">${svg('plus')}打开数据库</button><span class="native-note">JSON / CSV / SQLite</span></div><div class="section-line"><h2>已读取的数据库</h2><span>${files.length} 个文件</span></div><div class="db-file-list">${files.map(i=>`<div class="source-card" data-open="${i.id}" tabindex="0" role="button"><div class="source-icon">${svg('database')}</div><div class="source-info"><h3>${esc(i.filename)}</h3><p>${esc(i.recordCount!=null?i.recordCount+' 条记录 · '+i.extension:'按表分页读取 · '+i.extension)}</p><small>${bytes(i.size)}${i.error?' · 部分内容无法读取':''}</small></div><span>›</span></div>`).join('')||'<div class="empty-reader"><h3>还没有数据库文件</h3><p>打开现有的作品库或表格文件，即可逐表查看。</p></div>'}</div><div class="panel"><h3>通用条目资料</h3><p>名称、出品时间、类目、作者 / 主创、简介、标签是通用字段。支持电影、动漫、小说、漫画，也支持自定义类目。可以在资料库里手动添加条目，或补充已导入条目的资料。</p></div><div class="page-note">本版不会修改导入的原数据库。资料编辑另存于映迹的本地索引；SQLite 单文件支持 250 MB 以内，文本数据库支持 50 MB 以内。</div>`}
async function renderSettings(){$('#main').innerHTML=heading('PREFERENCES','你的资料，<em>你做主。</em>','离线使用，连接本地，按自己的方式整理。')+appearancePanel()+`<div class="panel"><h3>资料库与备份</h3><div class="panel-row"><div>本地索引<span style="display:block;margin-top:5px">包含条目元数据、文件位置和分类</span></div><button class="button small secondary" data-action="export-index">导出索引</button></div><div class="panel-row"><div>打开已有资料库<span style="display:block;margin-top:5px">JSON、CSV、SQLite 等格式</span></div><button class="button small secondary" data-action="files">选择文件</button></div><p class="hint">索引备份不包含图片和视频原件。迁移设备时，请同时保留素材文件；原文件移动后可重新读取文件夹。</p></div><div class="panel"><h3>AI 本机读取接口</h3><p>供你授权的 AI 查找条目、读取通用资料和浏览数据库表。当前只开放读取，不开放删除源文件或后台写入。</p><div class="connection-code" id="connectionInfo">正在获取本机连接信息…</div><div class="button-group"><button class="button small secondary" data-action="copy-connection">复制连接配置</button></div><p class="hint">连接密钥只应交给你信任的本机 AI 工具。程序关闭后接口随之关闭。</p></div><div class="panel"><h3>视频工具</h3><p>打开视频后，可截取当前画面为 PNG，或设置开始 / 结束时间导出 MP4 片段。轻度、中等、高压缩及自定义质量可选，默认中等。导出生成新文件，原素材保留。</p></div><div class="panel"><h3>关于映迹</h3><p>本地资料库 · Windows 桌面版 0.1.0<br>图片预览 / 视频处理 / 数据表浏览 / 通用条目资料<br>文件读取和媒体处理在本机完成。</p></div>`;try{const c=await invoke('connection');if($('#connectionInfo'))$('#connectionInfo').textContent=c?c.baseUrl+'\n认证：Bearer 密钥\n权限：只读\n配置文件：'+c.configPath:'连接接口正在启动，请稍后重新打开此页'}catch{if($('#connectionInfo'))$('#connectionInfo').textContent='在 Windows 桌面程序中使用本机接口'}}
function showSheet(html,cls=''){focusBefore=document.activeElement;$('#sheet').className='sheet '+cls;$('#sheet').innerHTML='<div class="sheet-grab"></div><button class="sheet-close" aria-label="关闭详情" data-action="close">×</button>'+html;$('#overlay').hidden=false;document.body.style.overflow='hidden';$('#sheet').focus()}
function closeSheet(){if(jobRunning){toast('视频正在导出，可先完成或取消任务');return}$('#sheet video')?.pause();$('#overlay').hidden=true;if(!window.YingjiMotion?.deferClear())$('#sheet').innerHTML='';document.body.style.overflow='';current=null;dbState=null;focusBefore?.focus?.()}
function metadata(i){return`<div class="metadata-grid"><div><label>类目</label><p>${esc(i.category||'未分类')}</p></div><div><label>出品时间</label><p>${esc(i.date||'未填写')}</p></div><div><label>作者 / 主创</label><p>${esc(i.author||'未填写')}</p></div><div><label>内容类型</label><p>${typeNames[i.type]}</p></div>${i.size?`<div><label>文件大小</label><p>${bytes(i.size)}</p></div><div><label>文件格式</label><p>${esc(i.extension)}</p></div>`:''}<div class="full"><label>来源</label><p>${esc(i.relativePath||i.source||'手动添加')}</p></div>${i.tags?`<div class="full"><label>标签</label><p>${esc(i.tags)}</p></div>`:''}${i.description?`<div class="full"><label>简介</label><p>${esc(i.description)}</p></div>`:''}</div>`}
async function openItem(id){const i=state.library.items.find(i=>i.id===id);if(!i)return;current=i;if(i.type==='database'){await openDatabase(i);return}if(i.type==='video'){openVideo(i);return}const img=i.type==='image'?`<div class="detail-preview"><img src="yingji-media://item/${i.id}" alt="${esc(i.title)}" id="detailImage"></div><button class="ghost-link" data-action="lightbox">全屏查看图片</button>`:'';const materials=(i.materialIds||[]).map(id=>state.library.items.find(x=>x.id===id)).filter(Boolean);showSheet(`<div class="detail-kicker">${i.type==='image'?'LOCAL IMAGE':'LIBRARY ENTRY'}</div><h2 class="detail-title">${esc(i.title)}</h2>${i.available===false?'<div class="error-note">源文件已移动或删除，请重新读取文件来源。</div>':''}${img}${metadata(i)}<div class="button-group"><button class="button small secondary" data-action="edit-current">编辑资料</button>${i.path?'<button class="button small secondary" data-action="reveal">在文件夹中显示</button>':''}</div>${i.type==='record'?`<div class="detail-section"><h3>关联素材 <small>${materials.length} 项</small></h3><button class="button small secondary" data-action="attach-material">添加图片或视频素材</button><div class="file-grid">${materials.map(card).join('')}</div><p class="hint">素材可通过编辑资料中的选择框关联。图片可以设为条目封面。</p></div>`:''}${i.raw?`<div class="detail-section"><h3>原始记录</h3>${rawFields(i.raw)}</div>`:''}`,'media-sheet');if($('#detailImage'))$('#detailImage').onerror=()=>toast('图片无法预览，格式可能不受支持');queueThumbnails()}
function rawFields(row){return`<dl>${Object.entries(row||{}).map(([k,v])=>`<div class="raw-field"><dt>${esc(k)}</dt><dd>${esc(typeof v==='object'?JSON.stringify(v,null,2):v)}</dd></div>`).join('')}</dl>`}
function openVideo(i){showSheet(`<div class="detail-kicker">LOCAL VIDEO</div><h2 class="detail-title">${esc(i.title)}</h2><div class="detail-preview"><video id="videoPlayer" src="yingji-media://item/${i.id}" controls preload="metadata" playsinline></video></div><div class="viewer-controls"><button class="button small secondary" data-action="back5">−5 秒</button><button class="button small secondary" data-action="forward5">+5 秒</button><button class="button small secondary" data-action="frame">${svg('frame')}截取当前画面</button><span class="time-readout" id="videoTime">00:00 / —</span></div><div class="clip-panel"><h3>片段导出</h3><div class="clip-range"><label>开始时间（秒）<input id="clipStart" type="number" min="0" step="0.01" value="0"><button class="set-time" data-action="set-start">使用当前播放位置</button></label><label>结束时间（秒）<input id="clipEnd" type="number" min="0" step="0.01" value="0"><button class="set-time" data-action="set-end">使用当前播放位置</button></label></div><div class="select-wrap"><select id="clipQuality" aria-label="导出压缩质量"><option value="light">轻度压缩 · 最高 1080p / CRF 20</option><option value="medium" selected>中等压缩 · 最高 720p / CRF 25（默认）</option><option value="strong">高压缩 · 最高 480p / CRF 31</option><option value="custom">自定义质量 · 最高 1080p</option></select></div><div id="customQuality" hidden><label class="form-label">CRF <output id="crfValue">25</output> · 数字越大，压缩越强</label><input id="clipCrf" type="range" min="16" max="38" value="25" style="width:100%;accent-color:#b9a5ff"></div><button class="button" data-action="clip" id="clipButton">导出所选片段</button><div id="exportProgress" hidden><div class="job-progress"><i id="exportBar" style="width:0%"></i></div><span class="native-note" id="exportText">正在处理…</span><button class="cancel-sync" data-action="cancel-job">取消任务</button></div><p class="clip-hint">生成 H.264 / AAC 的 MP4 副本，原文件保留。压缩为质量模式，实际文件大小取决于画面内容。</p></div><div id="videoInfo" class="video-extras">正在读取视频信息…</div><div class="button-group"><button class="button small secondary" data-action="edit-current">编辑资料</button><button class="button small secondary" data-action="reveal">在文件夹中显示</button></div>${metadata(i)}`,'media-sheet');const video=$('#videoPlayer');video.ontimeupdate=()=>{$('#videoTime').textContent=time(video.currentTime)+' / '+time(video.duration)};video.onloadedmetadata=()=>{$('#clipEnd').value=Number(video.duration.toFixed(2));$('#videoTime').textContent='00:00 / '+time(video.duration)};video.onerror=()=>toast('此视频编码无法直接预览，仍可尝试截帧或导出为 MP4');$('#clipQuality').onchange=e=>{$('#customQuality').hidden=e.target.value!=='custom'};$('#clipCrf').oninput=e=>{$('#crfValue').textContent=e.target.value};invoke('probe',i.id).then(info=>{if(current?.id!==i.id||!$('#videoInfo'))return;$('#videoInfo').textContent=`${info.width} × ${info.height} · ${time(info.duration)} · ${info.codec.toUpperCase()} · ${info.audio?'包含音轨':'无音轨'}`;if(!Number($('#clipEnd').value))$('#clipEnd').value=info.duration.toFixed(2)}).catch(e=>{if($('#videoInfo'))$('#videoInfo').textContent=e.message})}
async function mediaExport(frame){if(jobRunning||!current)return;const video=$('#videoPlayer');video?.pause();const args={id:current.id,time:video?.currentTime||0,start:Number($('#clipStart').value),end:Number($('#clipEnd').value),quality:$('#clipQuality').value,crf:Number($('#clipCrf').value)};if(!frame&&args.end<=args.start){toast('结束时间需要大于开始时间');return}jobRunning=true;$('#clipButton').disabled=true;$('#exportProgress').hidden=false;$('#exportText').textContent=frame?'正在导出 PNG 截图…':'选择保存位置后开始导出…';try{const result=await invoke(frame?'extract':'clip',args);toast(result?.canceled?'已取消导出':`已导出${frame?'截图':'片段'} · ${bytes(result.size)}，源文件保留`)}catch(e){toast(e.message)}finally{jobRunning=false;if($('#clipButton'))$('#clipButton').disabled=false;if($('#exportProgress'))$('#exportProgress').hidden=true}}
async function openDatabase(i){showSheet(`<div class="detail-kicker">DATABASE EXPLORER</div><h2 class="detail-title">${esc(i.filename)}</h2><p class="hint">只读浏览 · 原数据库不变</p><div id="databaseContent"><div class="loading-bar"><i></i></div><p class="loading-text">正在读取数据表…</p></div>`,'media-sheet');try{const tables=await invoke('database',{id:i.id});if(current?.id!==i.id)return;dbState={id:i.id,tables,table:tables[0]?.name,offset:0,query:'',limit:50};if(!tables.length){$('#databaseContent').innerHTML='<div class="empty-reader"><h3>这个数据库没有数据表</h3></div>';return}$('#databaseContent').innerHTML=`<div class="db-tables">${tables.map(t=>`<button class="chip ${t.name===dbState.table?'active':''}" data-table="${esc(t.name)}">${esc(t.name)} · ${t.count}</button>`).join('')}</div><div class="search db-search">${svg('search')}<input id="dbSearch" aria-label="搜索当前数据表" placeholder="搜索当前数据表…"></div><div id="dbRows"></div>${i.notice?`<p class="hint">${esc(i.notice)}</p>`:''}<button class="ghost-link" data-action="reveal">在文件夹中显示</button>`;let timer;$('#dbSearch').oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>{if(!dbState)return;dbState.query=e.target.value;dbState.offset=0;loadRows()},250)};await loadRows()}catch(e){if(current?.id!==i.id)return;if($('#databaseContent'))$('#databaseContent').innerHTML=`<div class="error-note">${esc(e.message)}</div>`}}
async function loadRows(){const query={...dbState};$('#dbRows').innerHTML='<div class="loading-bar"><i></i></div>';try{const r=await invoke('database',{id:query.id,table:query.table,q:query.query,offset:query.offset,limit:query.limit});if(!dbState||dbState.id!==query.id||dbState.table!==query.table||dbState.offset!==query.offset||dbState.query!==query.query)return;dbState.rows=r.rows;$('#dbRows').innerHTML=`<div class="section-line"><span>${r.total} 条记录 · ${r.columns.length} 个字段</span><span>点选记录查看全部字段</span></div><div class="table-scroll"><table><thead><tr>${r.columns.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${r.rows.map((row,idx)=>`<tr data-row="${idx}">${r.columns.map(c=>`<td title="${esc(typeof row[c]==='object'?JSON.stringify(row[c]):row[c])}">${esc(typeof row[c]==='object'?JSON.stringify(row[c]):row[c])}</td>`).join('')}</tr>`).join('')}</tbody></table>${!r.rows.length?'<div class="empty-reader"><p>没有匹配的记录</p></div>':''}</div><div class="table-pager"><button data-action="db-prev" ${query.offset===0?'disabled':''}>上一页</button><span>${r.total?query.offset+1:0}–${Math.min(query.offset+query.limit,r.total)} / ${r.total}</span><button data-action="db-next" ${query.offset+query.limit>=r.total?'disabled':''}>下一页</button></div>`}catch(e){if(!dbState||dbState.id!==query.id||dbState.table!==query.table||dbState.offset!==query.offset||dbState.query!==query.query)return;if($('#dbRows'))$('#dbRows').innerHTML=`<div class="error-note">${esc(e.message)}</div>`}}
function editEntry(item){const i=item||{title:'',date:'',author:'',category:'电影',description:'',tags:'',status:'pending',materialIds:[]};const cats=[...new Set([...YingjiCategories.DEFAULTS,...(state.library.categories||[])])],materials=state.library.items.filter(x=>['image','video'].includes(x.type));current=item||null;showSheet(`<div class="detail-kicker">UNIVERSAL METADATA</div><h2 class="detail-title">${item?'编辑条目资料':'添加一个新条目'}</h2><p class="hint">资料保存在映迹，源文件和原数据库不变。</p><form id="entryForm"><label class="form-label" for="entryTitle">名称 *</label><input class="form-input" id="entryTitle" name="title" required maxlength="500" value="${esc(i.title)}"><div class="form-row" style="margin-top:15px"><div><label class="form-label" for="entryCategory">类目 · 可自行填写</label><input class="form-input" name="category" id="entryCategory" list="categoryList" value="${esc(i.category)}"><datalist id="categoryList">${cats.map(c=>`<option value="${esc(c)}">`).join('')}</datalist></div><div><label class="form-label" for="entryDate">出品时间</label><input class="form-input" id="entryDate" name="date" placeholder="2024 或 2024-04-05" value="${esc(i.date)}"></div></div><label class="form-label" for="entryAuthor" style="margin-top:15px">作者 / 导演 / 主创</label><input class="form-input" id="entryAuthor" name="author" value="${esc(i.author)}"><label class="form-label" for="entryTags" style="margin-top:15px">标签</label><input class="form-input" id="entryTags" name="tags" placeholder="用逗号分隔，例如：科幻，治愈" value="${esc(i.tags)}"><label class="form-label" for="entryDescription" style="margin-top:15px">简介</label><textarea class="form-input" id="entryDescription" name="description">${esc(i.description)}</textarea><label class="form-label" for="entrySourceUrl" style="margin-top:15px">源网页（可选）</label><input class="form-input" id="entrySourceUrl" type="url" name="sourceUrl" placeholder="https://…" value="${esc(i.sourceUrl||'')}"><label class="form-label" for="entryStatus" style="margin-top:15px">观看状态</label><select id="entryStatus" name="status" class="status-select">${options(Object.entries(statusNames),i.status)}</select><label class="form-label" style="margin-top:18px" for="entryCover">条目封面</label><select class="status-select" name="coverId" id="entryCover">${options([['','暂不设置'],...materials.filter(m=>m.type==='image').map(m=>[m.id,m.title])],i.coverId||'')}</select><h3>关联素材</h3>${materials.length?`<div class="material-picker">${materials.map(m=>`<label class="check-line"><input type="checkbox" name="materials" value="${m.id}" ${(i.materialIds||[]).includes(m.id)?'checked':''}>${svg(m.type)}<span>${esc(m.title)}</span></label>`).join('')}</div>`:'<p class="hint">先读取图片或视频，就能在这里关联到条目。</p>'}<button class="button wide" type="submit" style="margin-top:20px">保存条目</button></form>`,'media-sheet');$('#entryForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const args={id:item?.id,...Object.fromEntries(f.entries()),materialIds:f.getAll('materials')};try{const r=await invoke('upsertEntry',args);state.library=r;closeSheet();state.tab='library';state.type='record';render();toast('条目资料已保存在本机')}catch(err){toast(err.message)}}}
document.addEventListener('click',async e=>{const tab=e.target.closest('[data-tab]');if(tab){state.tab=tab.dataset.tab;render();window.scrollTo(0,0);return}const type=e.target.closest('[data-type]');if(type){state.type=type.dataset.type;state.limit=40;renderLibrary();return}const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;localStorage.setItem('yingji-view',state.view);renderLibrary();return}const open=e.target.closest('[data-open]');if(open){openItem(open.dataset.open);return}const table=e.target.closest('[data-table]');if(table&&dbState){dbState.table=table.dataset.table;dbState.offset=0;document.querySelectorAll('[data-table]').forEach(b=>b.classList.toggle('active',b===table));loadRows();return}const row=e.target.closest('[data-row]');if(row&&dbState){const r=dbState.rows[Number(row.dataset.row)];const content=document.createElement('div');content.className='raw-popup';content.innerHTML=`<div class="raw-popup-inner"><button class="sheet-close" data-action="close-raw" aria-label="关闭记录">×</button><h3>完整记录</h3>${rawFields(r)}</div>`;$('#sheet').append(content);return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;try{switch(action){case'folder':await importFolder();break;case'files':await importFiles();break;case'rescan':await rescan();break;case'more':state.limit+=40;renderResults();break;case'close':closeSheet();break;case'close-raw':$('.raw-popup')?.remove();break;case'clear-filters':Object.assign(state,{query:'',type:'all',category:'all',year:'all',status:'all',materialFilter:'all'});renderLibrary();break;case'edit-new':editEntry();break;case'edit-current':editEntry(current);break;case'attach-material':{const target=current;const r=await invoke('chooseFiles');if(r){acceptLibrary(r);const still=state.library.items.find(i=>i.id===target.id);if(still){const ids=r.importedIds.filter(id=>state.library.items.some(i=>i.id===id&&['image','video'].includes(i.type)));const updated=await invoke('upsertEntry',{...still,materialIds:[...new Set([...(still.materialIds||[]),...ids])]});state.library=updated;await openItem(still.id);toast('素材已关联到条目');}}break}case'reveal':await invoke('reveal',current.id);break;case'copy-connection':await invoke('copyConnection');toast('连接配置已复制，请只交给受信任的本机工具');break;case'export-index':{const p=await invoke('exportIndex');if(p)toast('资料库索引已导出');break}case'lightbox':{const box=document.createElement('div');box.className='image-lightbox';box.innerHTML=`<img src="yingji-media://item/${current.id}" alt="${esc(current.title)}"><button aria-label="退出全屏">×</button>`;box.onclick=()=>box.remove();document.body.append(box);break}case'back5':$('#videoPlayer').currentTime=Math.max(0,$('#videoPlayer').currentTime-5);break;case'forward5':$('#videoPlayer').currentTime=Math.min($('#videoPlayer').duration||0,$('#videoPlayer').currentTime+5);break;case'set-start':$('#clipStart').value=$('#videoPlayer').currentTime.toFixed(2);break;case'set-end':$('#clipEnd').value=$('#videoPlayer').currentTime.toFixed(2);break;case'frame':await mediaExport(true);break;case'clip':await mediaExport(false);break;case'cancel-job':await invoke('cancelJob');break;case'db-prev':dbState.offset=Math.max(0,dbState.offset-50);await loadRows();break;case'db-next':dbState.offset+=50;await loadRows();break}}catch(err){toast(err.message)}});
$('#brandHome').onclick=e=>{e.preventDefault();state.tab='library';render()};$('#refreshTop').onclick=rescan;$('#overlay').onclick=e=>{if(e.target===$('#overlay'))closeSheet()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('.image-lightbox'))$('.image-lightbox').remove();else if($('.raw-popup'))$('.raw-popup').remove();else closeSheet()}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#searchInput')?.focus()}if(e.key==='Enter'&&e.target.matches('[data-open]'))openItem(e.target.dataset.open);if(e.key==='Tab'&&!$('#overlay').hidden){const nodes=[...$('#sheet').querySelectorAll('button:not(:disabled),input,select,textarea,[tabindex="0"]')].filter(n=>n.offsetParent);const first=nodes[0],last=nodes.at(-1);if(!first)return;if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('#sheet'))){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();dragDepth++;$('#dropZone').hidden=false}});document.addEventListener('dragover',e=>e.preventDefault());document.addEventListener('dragleave',()=>{dragDepth--;if(dragDepth<=0)$('#dropZone').hidden=true});document.addEventListener('drop',async e=>{e.preventDefault();dragDepth=0;$('#dropZone').hidden=true;try{const target=current;const r=await invoke('importDropped',Array.from(e.dataTransfer.files));acceptLibrary(r);if(target?.type==='record'){const still=state.library.items.find(i=>i.id===target.id);if(still){state.library=await invoke('upsertEntry',{...still,materialIds:[...new Set([...(still.materialIds||[]),...r.importedIds.filter(id=>state.library.items.some(i=>i.id===id&&['image','video'].includes(i.type)))])]});await openItem(still.id);toast('已将拖入的素材关联到条目');}}}catch(err){toast(err.message)}});
if(window.yingji)window.yingji.onProgress(p=>{if(p.kind==='scan'){if(window.onYingjiScanProgress)window.onYingjiScanProgress(p);else{scanCount=p.count;toast('正在读取本地文件… '+scanCount+' 项')}}if(p.kind==='export'&&$('#exportBar')){$('#exportBar').style.width=p.percent+'%';$('#exportText').textContent='正在导出… '+Math.round(p.percent)+'%'}});
(async()=>{try{try{preferences={...preferences,...await invoke('preferences')};applyPreferences()}catch{}const lib=await invoke('load');acceptLibrary(lib)}catch{$('#main').innerHTML=heading('WINDOWS DESKTOP APP','映迹<em>资料库。</em>','请启动 Windows 桌面程序，读取本地文件。')+'<div class="panel"><h3>本地资料库浏览器</h3><p>支持图片、视频、JSON、CSV 与 SQLite。运行程序文件后，点击“读取本地文件夹”开始使用。</p></div>'}})();
